test.describe('BottomSheet (lit) keyboard', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/iframe.html?id=bottomsheet-lit--keyboard&viewMode=story');
    await expect(page.getByRole('dialog').first()).toBeVisible();
  });
  test('Escape: Requests close with reason escape.', async ({ page }) => {
    const root = page.getByRole('dialog').first();
    await focusAt(page, root, 1);
    const before = await focusIndex(page, root);
    const stateBefore = await ariaState(page);
    void before; void stateBefore;
    await page.keyboard.press('Escape');
    await expect(root).toBeHidden();
  });
  test('Tab: From the last element wraps to the first; the handle is never a stop.', async ({ page }) => {
    const root = page.getByRole('dialog').first();
    await focusAt(page, root, await focusableCount(page, root) - 1);
    const before = await focusIndex(page, root);
    const stateBefore = await ariaState(page);
    void before; void stateBefore;
    await page.keyboard.press('Tab');
    expect(await focusIndex(page, root)).toBe(0);
  });
  test('Shift+Tab: From the first element wraps to the last.', async ({ page }) => {
    const root = page.getByRole('dialog').first();
    await focusAt(page, root, 0);
    const before = await focusIndex(page, root);
    const stateBefore = await ariaState(page);
    void before; void stateBefore;
    await page.keyboard.press('Shift+Tab');
    expect(await focusIndex(page, root)).toBe(await focusableCount(page, root) - 1);
  });
});
